import React, { useState } from "react";
import Stepper from "./Stepper";
import StyleFormPage from "./pages/StyleFormPage";
import WardrobeUploadPage from "./pages/WardrobeUploadPage";
import ChatbotPage from "./pages/ChatbotPage";
import HistoryPage from "./pages/HistoryPage";
import "./App.css";

function App() {
  const [step, setStep] = useState(0);
  const [styleInfo, setStyleInfo] = useState(null);
  const [history, setHistory] = useState([]);

  return (
    <div className="app-container">
      <h1>RewearAI Stylist</h1>
      <Stepper step={step} />
      {step === 0 && (
        <StyleFormPage onNext={info => { setStyleInfo(info); setStep(1); }} />
      )}
      {step === 1 && (
        <WardrobeUploadPage onNext={() => setStep(2)} />
      )}
      {step === 2 && (
        <ChatbotPage styleInfo={styleInfo} onAddToHistory={outfit => { setHistory([...history, outfit]); setStep(3); }} />
      )}
      {step === 3 && (
        <HistoryPage history={history} />
      )}
    </div>
  );
}

export default App;
